import type { JSX } from 'react'
import { useState } from 'react'
import { useNavigate } from 'react-router'

import { useAuth } from '@molecule/app-react'

import type { Article, SessionUser } from '../lib/api.js'
import { setFavorite } from '../lib/api.js'
import { useText } from '../lib/text.js'

interface FavoriteButtonProps {
  article: Article
  /** Compact styling for an article card in a list. */
  small?: boolean
  onChange?: (article: Article) => void
}

/**
 * Favorite / Unfavorite. The outline class means "not favorited yet", the solid
 * primary class means "favorited" — the convention the shared e2e tests assert.
 */
export function FavoriteButton({ article, small, onChange }: FavoriteButtonProps): JSX.Element {
  const text = useText()
  const navigate = useNavigate()
  const { status } = useAuth<SessionUser>()
  const [favorited, setFavorited] = useState(article.favorited)
  const [count, setCount] = useState(article.favoritesCount)
  const [pending, setPending] = useState(false)

  const onClick = async (): Promise<void> => {
    if (status !== 'authenticated') {
      navigate('/login')
      return
    }
    if (pending) return
    const next = !favorited
    setPending(true)
    setFavorited(next)
    setCount((current) => Math.max(0, current + (next ? 1 : -1)))
    try {
      const updated = await setFavorite(article.slug, next)
      setFavorited(updated.favorited)
      setCount(updated.favoritesCount)
      onChange?.(updated)
    } catch {
      setFavorited(!next)
      setCount((current) => Math.max(0, current + (next ? -1 : 1)))
    } finally {
      setPending(false)
    }
  }

  const classes = small
    ? `btn btn-sm pull-xs-right ${favorited ? 'btn-primary' : 'btn-outline-primary'}`
    : `btn btn-sm ${favorited ? 'btn-primary' : 'btn-outline-primary'}`

  return (
    <button type="button" className={classes} onClick={onClick}>
      <i className="ion-heart" />
      &nbsp;{favorited ? text('article.unfavorite', 'Unfavorite') : text('article.favorite', 'Favorite')}{' '}
      <span className="counter">({count})</span>
    </button>
  )
}

