import type { JSX } from 'react'
import { useState } from 'react'

import { useHttpClient } from '@molecule/app-react'

import type { ArticleSummary } from '../lib/conduit.js'
import { useLabels } from '../lib/conduit.js'

interface FavoriteButtonProps {
  article: ArticleSummary
  onChanged?: () => void
  /** The small heart + count button an article preview carries. */
  small?: boolean
}

/**
 * Favorite / Unfavorite. The API is the source of truth: the toggle is shown
 * optimistically and settles on whatever the answer says.
 */
export function FavoriteButton({ article, onChanged, small }: FavoriteButtonProps): JSX.Element {
  const label = useLabels()
  const http = useHttpClient()
  const [favorited, setFavorited] = useState(article.favorited)
  const [count, setCount] = useState(article.favoritesCount)
  const [pending, setPending] = useState(false)

  const toggle = async (): Promise<void> => {
    if (pending) return
    setPending(true)
    const next = !favorited
    setFavorited(next)
    setCount((value) => Math.max(0, value + (next ? 1 : -1)))
    try {
      const response = next
        ? await http.post(`/articles/${article.slug}/favorite`)
        : await http.delete(`/articles/${article.slug}/favorite`)
      const body = response.data as { article?: ArticleSummary } | undefined
      if (body?.article) {
        setFavorited(body.article.favorited)
        setCount(body.article.favoritesCount)
      }
      onChanged?.()
    } catch (_error) {
      setFavorited(!next)
      setCount((value) => Math.max(0, value + (next ? -1 : 1)))
    } finally {
      setPending(false)
    }
  }

  const className = `btn btn-sm ${favorited ? 'btn-primary' : 'btn-outline-primary'}${
    small ? ' pull-xs-right' : ''
  }`
  const text = favorited
    ? label('conduit.favorite.unfavorite', 'Unfavorite Article')
    : label('conduit.favorite.favorite', 'Favorite Article')

  return (
    <button
      type="button"
      className={className}
      onClick={() => {
        void toggle()
      }}
      data-mol-id="favorite-button"
    >
      <i className="ion-heart" /> {small ? count : `${text} (${count})`}
    </button>
  )
}

