import type { JSX } from 'react'
import { useEffect, useState } from 'react'
import { useNavigate } from 'react-router'

import { useAuth } from '@molecule/app-react'

import { favoriteArticle } from '../lib/api.js'

interface FavoriteButtonProps {
  slug: string
  favorited: boolean
  favoritesCount: number
  variant?: 'article' | 'preview'
  onChanged?: (favorited: boolean, favoritesCount: number) => void
}

/**
 * Favorite / Unfavorite. `.btn-outline-primary` while not favorited and
 * `.btn-primary` once favorited — the classes the RealWorld suite reads.
 */
export function FavoriteButton({
  slug,
  favorited,
  favoritesCount,
  variant = 'article',
  onChanged,
}: FavoriteButtonProps): JSX.Element {
  const { state } = useAuth()
  const navigate = useNavigate()
  const [isFavorited, setIsFavorited] = useState(favorited)
  const [count, setCount] = useState(favoritesCount)
  const [saving, setSaving] = useState(false)

  useEffect(() => {
    setIsFavorited(favorited)
    setCount(favoritesCount)
  }, [slug, favorited, favoritesCount])

  const toggle = async (): Promise<void> => {
    if (state.status !== 'authenticated') {
      navigate('/login')
      return
    }
    if (saving) return
    const next = !isFavorited
    setIsFavorited(next)
    setCount((current) => Math.max(0, current + (next ? 1 : -1)))
    setSaving(true)
    try {
      const article = await favoriteArticle(slug, next)
      setIsFavorited(article.favorited)
      setCount(article.favoritesCount)
      onChanged?.(article.favorited, article.favoritesCount)
    } catch {
      setIsFavorited(!next)
      setCount((current) => Math.max(0, current + (next ? -1 : 1)))
    } finally {
      setSaving(false)
    }
  }

  const className = isFavorited ? 'btn btn-primary btn-sm' : 'btn btn-outline-primary btn-sm'
  const label = isFavorited ? 'Unfavorite' : 'Favorite'

  return (
    <button type="button" className={className} onClick={toggle} data-mol-id={`favorite-${slug}`}>
      <i className="ion-heart" /> {variant === 'article' ? `${label} Article` : label}{' '}
      <span className="counter">({count})</span>
    </button>
  )
}

