import type { JSX } from 'react'
import { useEffect, useState } from 'react'
import { Link, useLocation, useNavigate, useParams } from 'react-router'

import { useAuth } from '@molecule/app-react'

import type { ConduitUser } from '../config.js'
import type { Article, Profile } from '../lib/api.js'
import { PAGE_SIZE, avatar, getProfile, listArticles, setFollow } from '../lib/api.js'
import { useLabel } from '../lib/i18n.js'
import { ArticleList, Pagination } from '../components/ArticleList.js'

export function ProfilePage(): JSX.Element {
  const label = useLabel()
  const { username = '' } = useParams<{ username: string }>()
  const location = useLocation()
  const navigate = useNavigate()
  const { user, status } = useAuth<ConduitUser>()

  const favourites = location.pathname.endsWith('/favorites')
  const [profile, setProfile] = useState<Profile | null>(null)
  const [articles, setArticles] = useState<Article[]>([])
  const [count, setCount] = useState(0)
  const [loading, setLoading] = useState(true)

  const ownProfile = Boolean(user?.username && user.username === username)

  useEffect(() => {
    let cancelled = false
    setProfile(null)
    getProfile(username)
      .then((loaded) => {
        if (!cancelled) setProfile(loaded)
      })
      .catch(() => {
        if (!cancelled) setProfile(null)
      })
    return () => {
      cancelled = true
    }
  }, [username, status])

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    const params = favourites ? { favorited: username, limit: PAGE_SIZE } : { author: username, limit: PAGE_SIZE }
    listArticles(params)
      .then((result) => {
        if (cancelled) return
        setArticles(result.articles)
        setCount(result.articlesCount)
      })
      .catch(() => {
        if (cancelled) return
        setArticles([])
        setCount(0)
      })
      .finally(() => {
        if (!cancelled) setLoading(false)
      })
    return () => {
      cancelled = true
    }
  }, [username, favourites])

  const toggleFollow = async (): Promise<void> => {
    if (!profile) return
    if (status !== 'authenticated') {
      navigate('/login')
      return
    }
    const next = !profile.following
    setProfile({ ...profile, following: next })
    try {
      const updated = await setFollow(profile.username, next)
      setProfile(updated)
    } catch {
      setProfile(profile)
    }
  }

  return (
    <div className="profile-page">
      <div className="user-info">
        <div className="container">
          <div className="row">
            <div className="col-xs-12 col-md-10 offset-md-1">
              <img className="user-img" src={avatar(profile?.image)} alt="" />
              <h4>{username}</h4>
              <p>{profile?.bio ?? ''}</p>
              {ownProfile ? (
                <Link className="btn btn-sm btn-outline-secondary action-btn" to="/settings">
                  <i className="ion-gear-a" />{' '}
                  {label('conduit.profile.editSettings', 'Edit Profile Settings')}
                </Link>
              ) : (
                <button
                  className="btn btn-sm btn-outline-secondary action-btn"
                  type="button"
                  onClick={() => {
                    void toggleFollow()
                  }}
                >
                  <i className="ion-plus-round" />{' '}
                  {profile?.following
                    ? label('conduit.profile.unfollow', 'Unfollow')
                    : label('conduit.profile.follow', 'Follow')}{' '}
                  {username}
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      <div className="container">
        <div className="row">
          <div className="col-xs-12 col-md-10 offset-md-1">
            <div className="articles-toggle">
              <ul className="nav nav-pills outline-active">
                <li className="nav-item">
                  <Link
                    className={favourites ? 'nav-link' : 'nav-link active'}
                    to={`/profile/${username}`}
                  >
                    {label('conduit.profile.myArticles', 'My Articles')}
                  </Link>
                </li>
                <li className="nav-item">
                  <Link
                    className={favourites ? 'nav-link active' : 'nav-link'}
                    to={`/profile/${username}/favorites`}
                  >
                    {label('conduit.profile.favorited', 'Favorited Articles')}
                  </Link>
                </li>
              </ul>
            </div>

            <ArticleList
              articles={articles}
              loading={loading}
              emptyMessage={
                <div className="empty-feed-message">
                  <p>{label('conduit.profile.empty', 'No articles are here... yet.')}</p>
                </div>
              }
            />

            {!loading ? (
              <Pagination
                currentPage={1}
                total={count}
                pageSize={PAGE_SIZE}
                hrefFor={() => (favourites ? `/profile/${username}/favorites` : `/profile/${username}`)}
              />
            ) : null}
          </div>
        </div>
      </div>
    </div>
  )
}

