import { useNavigate } from 'react-router'

import { useAuth, useOptimisticValue } from '@molecule/app-react'

import { favoriteArticle, followUser } from '../lib/api.js'
import { useLabel } from './label.js'

interface FavoriteProps {
  slug: string
  favorited: boolean
  favoritesCount: number
  /** Preview variant renders the bare counter, as Conduit's feed does. */
  compact?: boolean
}

interface FavoriteValue {
  favorited: boolean
  count: number
}

export function FavoriteButton({
  slug,
  favorited,
  favoritesCount,
  compact = false,
}: FavoriteProps) {
  const label = useLabel()
  const navigate = useNavigate()
  const { status } = useAuth()
  const { value, update } = useOptimisticValue<FavoriteValue>({
    value: { favorited, count: favoritesCount },
    equals: (a, b) => a.favorited === b.favorited && a.count === b.count,
    commit: async (next) => {
      const { article } = await favoriteArticle(slug, next.favorited)
      return { favorited: article.favorited, count: article.favoritesCount }
    },
  })

  return (
    <button
      type="button"
      className={value.favorited ? 'btn btn-primary btn-sm' : 'btn btn-outline-primary btn-sm'}
      onClick={() => {
        if (status !== 'authenticated') {
          navigate('/login')
          return
        }
        update((current) => ({
          favorited: !current.favorited,
          count: current.count + (current.favorited ? -1 : 1),
        }))
      }}
      data-mol-id="favorite-button"
    >
      <i className="ion-heart" />
      &nbsp;
      {compact
        ? null
        : value.favorited
          ? label('article.unfavorite', 'Unfavorite')
          : label('article.favorite', 'Favorite')}
      <span className="counter">{compact ? ` ${value.count}` : ` (${value.count})`}</span>
    </button>
  )
}

interface FollowProps {
  username: string
  following: boolean
}

export function FollowButton({ username, following }: FollowProps) {
  const label = useLabel()
  const navigate = useNavigate()
  const { status } = useAuth()
  const { value: isFollowing, update } = useOptimisticValue<boolean>({
    value: following,
    equals: (a, b) => a === b,
    commit: async (next) => {
      const { profile } = await followUser(username, next)
      return profile.following
    },
  })

  return (
    <button
      type="button"
      className="btn btn-sm btn-outline-secondary action-btn"
      onClick={() => {
        if (status !== 'authenticated') {
          navigate('/login')
          return
        }
        update((current) => !current)
      }}
      data-mol-id="follow-button"
    >
      {isFollowing
        ? label('profile.unfollow', 'Unfollow') + ` ${username}`
        : label('profile.follow', 'Follow') + ` ${username}`}
    </button>
  )
}
